  { id: "csx", name: "CSX", region: "East", speed2019: 24.1, speedTrough: 21.2, speed2026: 23.6, dwell2019: 22.8, dwellPeak: 26.9, dwell2026: 21.5, speedRecoveryPct: 83, confidence: "estimated" },
