  { id: "cn", name: "CN (U.S.)", region: "North", speed2019: 24.6, speedTrough: 21.8, speed2026: 24.0, dwell2019: 20.9, dwellPeak: 25.4, dwell2026: 20.4, speedRecoveryPct: 79, confidence: "estimated" },
