export type TerminalRow = {
  id: string;
  name: string;
  corridor: string;
  carrier: string;
  /** Dwell hours 2019 baseline */
  dwell2019: number;
  /** Dwell hours 2022 peak */
  dwellPeak: number;
  /** Dwell hours 2026Q2 */
  dwell2026: number;
  /** Lag vs 2019: positive = still worse (hours) */
